        { t: "mcq", q: "Would you mind ____ the window? It's rather cold in here.", o: ["to close", "close", "closing", "closed"], a: 2, x: "بعد Would you mind نستخدم V-ing: Would you mind closing the window? وهي صيغة طلب مهذب جداً." },
        { t: "mcq", q: "My grandmother ____ have a small shop in Salt, but she sold it years ago.", o: ["would", "was used to", "has used to", "used to"], a: 3, x: "have هنا بمعنى «تملك» (فعل حالة) ← نستخدم used to ولا نستخدم would للحالات. وwas used to تعني «كانت معتادة على» وتأتي مع V-ing." },
        { t: "gap", q: "He said he ____ (call) me back after the meeting, but he never did.", a: ["would call", "'d call", "d call", "was going to call"], x: "مستقبل في الماضي بعد said ← would + V1 (أو was going to). الكلام المباشر هو: 'I will call you back.'" },
        { t: "mcq", q: "In 2010, young Omar had no idea that he ____ one day lead the school's science club.", o: ["will", "would", "is going to", "has"], a: 1, x: "كانت قيادة النادي أمراً مستقبلياً بالنسبة إلى سنة 2010 ← مستقبل في الماضي ← would. أما will وis going to فتدلان على الحاضر أو المستقبل الحالي." },
        { t: "tr", q: "'I will meet you at the station,' said Ahmad.", p: "Rewrite starting with: Ahmad said …", a: ["Ahmad said he would meet me at the station.", "Ahmad said that he would meet me at the station.", "Ahmad said he'd meet me at the station.", "Ahmad said that he'd meet me at the station.", "Ahmad said hed meet me at the station.", "Ahmad said that hed meet me at the station."], x: "في الكلام المنقول بعد فعل ماضٍ تتحول will إلى would، ويتغير الضمير I إلى he وyou إلى me." },
        { t: "mcq", q: "Our old car ____ start this morning, so we had to call a mechanic.", o: ["wouldn't", "won't", "doesn't", "can't"], a: 0, x: "الحدث ماضٍ (this morning … had to call) ← wouldn't بمعنى «رفضت» أن تعمل. أما won't فللحاضر." },
        { t: "order", a: "Would you mind lending me your pen?", x: "Would you mind + V-ing: طلب مهذب جداً (lending me your pen)." },
        { t: "mcq", q: "If she had left earlier, she ____ the train.", o: ["would catch", "will have caught", "would have caught", "had caught"], a: 2, x: "الشرط الثالث (موقف خيالي في الماضي): if + past perfect + would have + V3." },
        { t: "gap", q: "If you had told me about the problem, I ____ (would / help) you.", a: ["would have helped", "'d have helped", "d have helped", "would've helped", "wouldve helped"], x: "الشرط الثالث ← would have + V3: I would have helped you." },
        { t: "mcq", q: "I'd rather you ____ your phone in the cinema; it distracts other people.", o: ["won't use", "not to use", "using", "didn't use"], a: 3, x: "would rather + شخص آخر + past simple للتعبير عن تفضيل بخصوص فعل شخص آخر في الحاضر أو المستقبل: I'd rather you didn't use…" },
        { t: "err", q: "When I was little, I would have a pet parrot called Zozo.", w: "would", c: "used to", x: "have هنا بمعنى «أملك» (حالة) فلا نستعمل معه would للماضي، بل used to: I used to have a pet parrot." },
        { t: "tr", q: "I prefer to stay at home tonight.", p: "Rewrite using WOULD RATHER: I …", a: ["I would rather stay at home tonight.", "I'd rather stay at home tonight.", "Id rather stay at home tonight."], x: "would rather + V1 بدون to." },
        { t: "gap", q: "I'd rather you ____ (not / tell) anyone about the surprise until the party tomorrow.", a: ["didn't tell", "did not tell", "didnt tell"], x: "would rather + شخص آخر + past simple: I'd rather you didn't tell… (الماضي هنا يدل على الحاضر أو المستقبل، وكلمة tomorrow تؤكد أن الكلام عن المستقبل؛ أما للندم على شيء مضى فنستخدم past perfect: I'd rather you hadn't told…)." },
        { t: "err", q: "If I wouldn't live so far from school, I would walk there every day.", w: "wouldn't", c: "didn't", x: "في الشرط الثاني نستخدم past simple في جملة if (If I didn't live…) ولا نضع would فيها؛ أما would فمكانها جملة النتيجة فقط (I would walk)." },
        { t: "order", a: "She would rather walk than wait for the bus.", x: "would rather + V1 + than + V1: كلاهما بدون to." }
